function twoLoners(nums: number[]): number[] {
  let x = 0;
  for (const v of nums) x ^= v;
  const bit = x & -x; // lowest bit where the two loners differ
  let first = 0;
  for (const v of nums) if (v & bit) first ^= v;
  return [first, x ^ first];
}

